                ctx.delete(record)
            }
            try ctx.save()
            AppLogger.shared.info("ChaosStress", "cleanup_completed", metadata: ["count": toDelete.count])
        } catch {
            AppLogger.shared.error("ChaosStress", "cleanup_failed", metadata: ["error": "\(error)"])
        }
    }

