    let weekKey: String
    let startedAt: Date
    /// 进行到哪一阶段(诊断用;判定"是否被中断"只看记录在不在)。
    var phase: String
}

/// 持久化的备份状态。
struct BackupState: Codable {
    /// 非 nil = 有一次尝试没有正常收尾。**下次启动读到它就说明上次被中断。**
    var inFlight: BackupAttemptRecord?
    /// 被抑制的周。该周不再自动备份。
    var suppressedWeekKey: String?
    /// 最近一次可恢复失败的原因(诊断用,不影响资格)。
    var lastDeferredReason: String?
