                try? fm.removeItem(at: partial)
                throw StagingError.totalTooLarge(bytes: copied)
            }
        }

        try? fm.removeItem(at: final)
        do {
            try fm.moveItem(at: partial, to: final)
        } catch {
            try? fm.removeItem(at: partial)
